import { useState, useRef } from 'react';

const logo = {
  alt: 'Old Mate Cranes & Rigging',
  url: 'logo01.png',
  width: 240,
  href: 'http://localhost:3000/'

};

const menu = {
  link1:{
    copy:'home',
    url: 'http://localhost:3000/'
  },
  link2:{
    copy:'about us',
    url:'#aboutus'
  },
  link3:{
    copy:'contact',
    url: '#contact'
  },
  link4:{
    copy:'services',
    url:'#services'
  },
  link5:{
    copy:'safety',
    url: '#safety'
  },
  link6:{
    copy:'industrial',
    url:'#industrial'
  },
  link7:{
    copy:'civil',
    url:'#civil'
  }
};


const Menu = () =>  {

  const [show, setShow] = useState(false);
  const ref = useRef(null);
  const toggle = () =>  ( setShow(!show));

return(
    <>
    <nav className='navbar fixed-top bg-body-tertiary' role='navigation'>
    <div className='container-fluid d-flex'>
    <a className='navbar-brand' href={logo.href}><img src={logo.url} alt={logo.alt} width={logo.width} /></a>
    <button className='navbar-toggler' type='button' aria-label='Toggle navigation'>
      <span className='navbar-toggler-icon'  onClick={toggle}></span>
    </button>
    </div>
    </nav>
    </>
  )

};



export default Menu;
